 function renderRoomTemplate(model){const host=$('tvxRoomPreview');if(!host)return;const t=ROOM_MODELS[model]||ROOM_MODELS.luxury;const total=t.rooms.reduce((s,x)=>s+x[1],0);host.innerHTML=`<div class="tvx-mansion-room-grid">${t.rooms.map(([name,r])=>`<div class="tvx-mansion-room-chip"><b>${esc(name)}</b><span>${f(r/total*100,0)}% of usable programme area</span></div>`).join('')}</div>`;}
 function coordinationSummary(){if(!latest)return 'No calculated building model. Enter verified site and programme inputs.';const checks=[];checks.push({name:'Setback envelope',ok:latest.clearLength>0&&latest.clearWidth>0,detail:`${f(latest.clearLength,2)} × ${f(latest.clearWidth,2)} m remaining`});checks.push({name:'Coverage cap',ok:latest.geometricFootprint<=latest.coverageCap+1e-7,detail:`${f(latest.geometricFootprint,2)} / ${f(latest.coverageCap,2)} m²`});if(latest.farLimit!==null)checks.push({name:'Entered FAR / FSI limit',ok:latest.farWithinLimit,detail:`${f(latest.actualFAR,2)} / ${f(latest.farLimit,2)}`});if(latest.levels>8)checks.push({name:'Structural solver scope',ok:null,detail:'Planning supports up to 60 levels; representative 2D frame solver supports only 1–8.'});if(latestVertical){const li=latestVertical.lift;if(li.shaftWidthM!==null&&li.shaftDepthM!==null){const fit=li.shaftWidthM<=Math.max(latest.dimensionLength,latest.dimensionWidth)&&li.shaftDepthM<=Math.max(latest.dimensionLength,latest.dimensionWidth);checks.push({name:'Lift-shaft dimensional envelope',ok:fit,detail:fit?'Shaft dimensions fit the overall envelope only; exact placement not checked.':'Shaft exceeds building envelope dimension.'});if(li.clearance)checks.push({name:'Lift car / shaft dimensional difference',ok:li.clearance.width>0&&li.clearance.depth>0,detail:`Clearance difference ${f(li.clearance.width,2)} × ${f(li.clearance.depth,2)} m; vendor GA required.`});}checks.push({name:'Lift rated passenger mass',ok:li.capacityMassOK,detail:li.capacityStatus});checks.push({name:'Lift vendor GA',ok:li.vendorGAComplete,detail:li.vendorGAComplete?'Required vendor geometry/reaction fields entered; supplier drawing still required.':'Shaft, pit, overhead, door or support reaction data incomplete.'});checks.push({name:'Lift population / traffic basis',ok:li.population!==null,detail:li.population===null?'Enter code/occupancy-derived project population.':'User-entered population '+li.population});const st=latestVertical.stair;checks.push({name:'Stair comparison inputs',ok:st.comparisons.every(x=>x.ok!==null),detail:st.comparisonStatus});}else checks.push({name:'Stairs and lifts',ok:null,detail:'Run vertical-circulation analysis.'});if(latestRoof){checks.push({name:'Roof tank load path inputs',ok:latestRoof.waterTankVolumeM3===0||latestRoof.tankFootprintM2!==null,detail:latestRoof.waterTankVolumeM3===0?'No water tank modelled':'Localized tank support footprint entered'});checks.push({name:'Roof service-zone area',ok:latestRoof.roofZoneAreaM2<=latestRoof.roofAreaM2+1e-8,detail:`${f(latestRoof.roofZoneAreaM2,1)} / ${f(latestRoof.roofAreaM2,1)} m² for PV + green + tank areas`});}else checks.push({name:'Roof design',ok:null,detail:'Run roof analysis.'});if(latestFacade){checks.push({name:'Exterior wind / cladding basis',ok:latestFacade.netWindPressureKPA!==null&&latestFacade.claddingDeadLoadKN!==null,detail:'Net wind pressure and tested cladding dead load must be entered.'});}else checks.push({name:'Exterior / balconies',ok:null,detail:'Run exterior analysis.'});if(!latest.codeEdition)checks.push({name:'Adopted code edition / amendment',ok:null,detail:'Exact legal edition and local amendments not recorded.'});const nFail=checks.filter(x=>x.ok===false).length,nUnknown=checks.filter(x=>x.ok===null).length;return `${checks.length} coordination gates · ${nFail} entered-limit failure(s) · ${nUnknown} unresolved item(s). This is a completeness screen, not BIM clash detection or code certification.\n`+checks.map(x=>`${x.ok===true?'[PASS]':x.ok===false?'[FAIL]':'[OPEN]'} ${x.name}: ${x.detail}`).join('\n');}
