  const preview=$('tvxMansionVerticalPreview');if(preview){const width=840,height=320,steps=Math.min(stair.risers,32),stepW=480/steps,stairPath=Array.from({length:steps},(_,j)=>`H${80+(j+1)*stepW}V${240-(j+1)*Math.min(5,180/steps)}`).join(' ');const shaft=lift.shaftWidthM&&lift.shaftDepthM?`<rect x="590" y="70" width="${Math.max(40,lift.shaftWidthM*30)}" height="${Math.max(50,lift.shaftDepthM*30)}" fill="#173d4d" stroke="#a6d9e2" stroke-width="2"/><rect x="600" y="80" width="${Math.max(20,lift.carWidthM*30)}" height="${Math.max(20,lift.carDepthM*30)}" fill="#397082" stroke="#f0d5a5"/><text x="590" y="55" fill="#d4f5fa" font-size="13">LIFT SHAFT / CAR</text>`:`<text x="590" y="120" fill="#d6e8ed" font-size="14">Enter vendor shaft dimensions</text>`;preview.innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Stair section and lift shaft schematic"><rect width="100%" height="100%" fill="#071927"/><path d="M50 260H520M70 260 ${stairPath}" fill="none" stroke="#9ee0e8" stroke-width="4"/><path d="M300 90h220v170h-220" fill="none" stroke="#426a78" stroke-width="2" stroke-dasharray="5 4"/><text x="80" y="35" fill="#d6f3f7" font-size="14">${esc(stair.type.toUpperCase())} STAIR · ${stair.risers} RISERS · ${f(stair.actualRiserMM,1)} mm ACTUAL</text><text x="80" y="290" fill="#95c5d0" font-size="12">SCHEMATIC STAIR FLIGHT · CHECK LANDINGS / HEADROOM / EGRESS WITH ADOPTED CODE</text>${shaft}</svg>`;}
