 function currentReport(){return {product:'TERRAVEX APEX v50 Universal Building & Mansion Design Workbench',timestamp:new Date().toISOString(),project:latest,levels:latestFloors,vertical:latestVertical,roof:latestRoof,facade:latestFacade,representativeFrame:latestFrame,selectedRoomModel:$('tvxRoomModel')?.value,roomStyle:$('tvxRoomStyle')?.value,codeBasis:{structural:CODE_PROFILES[latest?.codeProfile]||null,fire:FIRE_PROFILES[latest?.fireCode]||null,lift:LIFT_PROFILES[latest?.liftCode]||null},releaseStatus:'DESIGN DEVELOPMENT / NOT FOR CONSTRUCTION',coordinationSummary:coordinationSummary(),mandatoryLimitations:['No construction approval or professional seal is generated.','Complete 3D analysis and independent code/member checks are required.','Survey, geotechnical, material testing, fire, MEP, lift-vendor and local authority documentation remain required.']};}
 function download(name,type,content){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);}
 function csvRows(rows){const q=x=>'"'+String(x??'').replace(/"/g,'""')+'"';return rows.map(row=>row.map(q).join(',')).join('\r\n');}
