 function exportDXF(){try{if(!latest)calculate();if(!latest)throw new Error('No project model.');if(!latestRoof)roofAnalysis();if(!latestFacade)facadeAnalysis();if(!latestVertical)verticalAnalysis();const dxf=makeDXF();download('TERRAVEX-v50-All-Level-Architecture-Review-R12.dxf','application/dxf;charset=utf-8',dxf);const st=$('tvxMansionExportStatus');if(st)st.textContent='DXF R12 / AC1009 EXPORTED · REVIEW SHEETS ONLY · NOT FOR CONSTRUCTION';}catch(e){const st=$('tvxMansionExportStatus');if(st)st.textContent='DXF EXPORT BLOCKED · '+e.message;}}
 function saveLocal(){const fields=Array.from(document.querySelectorAll('#tvxMansionStudio input,#tvxMansionStudio select')).filter(x=>x.id).map(x=>({id:x.id,value:x.type==='checkbox'?x.checked:x.value}));const floorRows=floorRolesFromUI();try{localStorage.setItem(STORAGE_KEY,JSON.stringify({fields,floorRows,savedAt:new Date().toISOString()}));return true;}catch(_){return false;}}
 function loadLocal(){try{const data=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(!data)return false;(data.fields||[]).forEach(x=>{const el=$(x.id);if(el){if(el.type==='checkbox')el.checked=!!x.value;else el.value=x.value;}});if(data.floorRows&&latest){renderRoleRows(Number($('tvxMansionLevels')?.value||latest.levels));data.floorRows.forEach((r,i)=>{const row=document.querySelector(`[data-mansion-floor="${i}"]`);if(row){row.querySelector('[data-floor-role]').value=r.role;row.querySelector('[data-floor-model]').value=r.model;row.querySelector('[data-floor-balcony-count]').value=r.balconyCount;row.querySelector('[data-floor-balcony-depth]').value=r.balconyDepth;row.querySelector('[data-floor-balcony-width]').value=r.balconyWidth;}});}calculate();verticalAnalysis();roofAnalysis();facadeAnalysis();return true;}catch(_){return false;}}
 function command(cmd){const c=String(cmd||'').trim().toUpperCase().replace(/\s+/g,' ');let message='';if(c==='HELP'||c==='?')message='COMMANDS: CALCULATE · FLOOR n · ROOM model · STAIR CHECK · LIFT CHECK · VERTICAL CHECK · ROOF CHECK · FACADE CHECK · FRAME RUN · COORDINATION CHECK · RUN ALL · EXPORT DXF · REPORT JSON · SAVE LOCAL · LOAD LOCAL · SHAPE rectangle|square|L|U|courtyard|circle';
  else if(c==='CALCULATE'||c==='MANSION CALCULATE'){message=calculate()?'Building envelope and floor programme recalculated.':'Calculation blocked. Check the site input status.';}
  else if(/^FLOOR \d+$/.test(c)){if(!latest)calculate();const n=Number(c.split(' ')[1]),sel=$('tvxMansionFloorSelect');if(n<0||n>=latestFloors.length)message='Floor index outside the current project levels.';else if(sel){sel.value=String(n);renderPlan(latestFloors[n]);message='Preview set to '+latestFloors[n].floorName+'.';}}
  else if(c==='STAIR CHECK'||c==='LIFT CHECK'||c==='VERTICAL CHECK'){message=verticalAnalysis()?'Stair and lift review updated.':'Vertical review blocked; see status.';}
  else if(c==='ROOF CHECK'){message=roofAnalysis()?'Roof screening updated.':'Roof review blocked; see status.';}
  else if(c==='FACADE CHECK'||c==='EXTERIOR CHECK'){message=facadeAnalysis()?'Exterior take-off updated.':'Exterior review blocked; see status.';}
  else if(c==='FRAME RUN'){message=frameAnalysis()?'Representative 2D frame solved.':'Frame solver blocked; see status.';}
  else if(c==='COORDINATION CHECK'){message=coordinationSummary();const host=$('tvxMansionCoordination');if(host)host.textContent=message;}
  else if(c.startsWith('ROOM ')){const model=c.slice(5).toLowerCase();if(ROOM_MODELS[model]&&$('tvxRoomModel')){$('tvxRoomModel').value=model;document.querySelectorAll('[data-floor-model]').forEach(el=>el.value=model);renderRoomTemplate(model);if(latest)recalculateFloors();message='Room model set to '+model+'.';}else message='Unknown room model. Use '+Object.keys(ROOM_MODELS).join(', ')+'.';}
  else if(c.startsWith('FACADE STYLE ')){const style=c.slice(13).toLowerCase();if(['tropical','contemporary','classical','minimal','courtyard','colonial','biophilic','brutalist'].includes(style)&&$('tvxFacadeStyle')){$('tvxFacadeStyle').value=style;renderElevation();if(latest)facadeAnalysis();message='Facade style set to '+style+'.';}else message='Unknown facade style.';}
  else if(c==='RUN ALL'){const a=calculate();if(a){verticalAnalysis();roofAnalysis();facadeAnalysis();if(a.levels<=8)frameAnalysis();const summary=coordinationSummary();const coordinationHost=$('tvxMansionCoordination');if(coordinationHost)coordinationHost.textContent=summary;message='Review sequence finished and coordination gates refreshed. Check every panel for missing evidence and blocked analyses.';}else message='Run sequence stopped: site / envelope input invalid.';}
  else if(c==='EXPORT DXF'){exportDXF();message='DXF export requested. Check the export status.';}
  else if(c==='REPORT JSON'){exportJSON();message='Design review JSON export requested.';}
  else if(c==='SAVE LOCAL'){message=saveLocal()?'Project saved to this browser only.':'Local browser storage unavailable or full.';}
  else if(c==='LOAD LOCAL'){message=loadLocal()?'Local project loaded.':'No valid local project snapshot found.';}
  else if(c.startsWith('SHAPE ')){const shape=c.slice(6).toLowerCase();const val=shape==='l'?'L':shape==='u'?'U':shape;if(SHAPE_EFF[val]&&$('tvxMansionShape')){$('tvxMansionShape').value=val;message=calculate()?'Shape set to '+val+'.':'Shape changed; calculation blocked until inputs are valid.';}else message='Unknown shape. Use rectangle, square, L, U, courtyard or circle.';}
  else message='UNKNOWN COMMAND · type HELP to see supported commands.';
  const out=$('tvxMansionCommandOutput');if(out)out.textContent=message;return {command:c,message};
 }
